package dev.epoch;

import java.io.*;
import java.util.*;
import net.minecraft.nbt.*;

/** Canonical SNBT bridge. 1.7's native list toString adds indices and is not modern SNBT. */
final class LegacyNbt {
 static final class Tag {final int type;Object value;Tag(int t,Object v){type=t;value=v;}}
 static Tag compound(){return new Tag(10,new LinkedHashMap<String,Tag>());}
 @SuppressWarnings("unchecked") static Map<String,Tag> map(Tag t){return (Map<String,Tag>)t.value;}
 @SuppressWarnings("unchecked") static List<Tag> list(Tag t){return (List<Tag>)t.value;}
 static String string(Tag t){return t==null?"":String.valueOf(t.value);}
 static Tag from(NBTTagCompound nativeTag)throws IOException {ByteArrayOutputStream bytes=new ByteArrayOutputStream();CompressedStreamTools.write(nativeTag,new DataOutputStream(bytes));DataInputStream input=new DataInputStream(new ByteArrayInputStream(bytes.toByteArray()));int type=input.readUnsignedByte();input.readUTF();return read(input,type,0);}
 static NBTTagCompound nativeTag(Tag tag)throws IOException {ByteArrayOutputStream bytes=new ByteArrayOutputStream();DataOutputStream out=new DataOutputStream(bytes);out.writeByte(10);out.writeUTF("");write(out,tag);return CompressedStreamTools.read(new DataInputStream(new ByteArrayInputStream(bytes.toByteArray())));}
 static Tag read(DataInput in,int type,int depth)throws IOException {
  if(depth>128)throw new IOException("NBT nesting too deep");
  switch(type){case 1:return new Tag(type,in.readByte());case 2:return new Tag(type,in.readShort());case 3:return new Tag(type,in.readInt());case 4:return new Tag(type,in.readLong());case 5:return new Tag(type,in.readFloat());case 6:return new Tag(type,in.readDouble());case 8:return new Tag(type,in.readUTF());case 7:{int n=in.readInt();if(n<0||n>16777216)throw new IOException("NBT array too large");byte[] v=new byte[n];in.readFully(v);return new Tag(type,v);}case 11:{int n=in.readInt();if(n<0||n>4194304)throw new IOException("NBT array too large");int[] v=new int[n];for(int i=0;i<n;i++)v[i]=in.readInt();return new Tag(type,v);}case 9:{int subtype=in.readUnsignedByte(),n=in.readInt();if(n<0||n>1000000)throw new IOException("NBT list too large");List<Tag> v=new ArrayList<Tag>();for(int i=0;i<n;i++)v.add(read(in,subtype,depth+1));return new Tag(type,v);}case 10:{Tag v=compound();for(int t;(t=in.readUnsignedByte())!=0;)map(v).put(in.readUTF(),read(in,t,depth+1));return v;}default:throw new IOException("NBT type unavailable in 1.7.10: "+type);}
 }
 static void write(DataOutput out,Tag tag)throws IOException {
  switch(tag.type){case 1:out.writeByte(((Number)tag.value).byteValue());break;case 2:out.writeShort(((Number)tag.value).shortValue());break;case 3:out.writeInt(((Number)tag.value).intValue());break;case 4:out.writeLong(((Number)tag.value).longValue());break;case 5:out.writeFloat(((Number)tag.value).floatValue());break;case 6:out.writeDouble(((Number)tag.value).doubleValue());break;case 8:out.writeUTF((String)tag.value);break;case 7:{byte[] v=(byte[])tag.value;out.writeInt(v.length);out.write(v);break;}case 11:{int[] v=(int[])tag.value;out.writeInt(v.length);for(int n:v)out.writeInt(n);break;}case 9:{List<Tag> v=list(tag);int type=v.isEmpty()?0:v.get(0).type;out.writeByte(type);out.writeInt(v.size());for(Tag t:v){if(t.type!=type)throw new IOException("Mixed NBT list");write(out,t);}break;}case 10:{for(Map.Entry<String,Tag> e:map(tag).entrySet()){out.writeByte(e.getValue().type);out.writeUTF(e.getKey());write(out,e.getValue());}out.writeByte(0);break;}default:throw new IOException("Unsupported NBT type "+tag.type);}
 }
 static String encode(NBTTagCompound tag)throws IOException{return encode(from(tag));}
 static String quote(String s){return "\""+s.replace("\\","\\\\").replace("\"","\\\"")+"\"";}
 static String encode(Tag tag){switch(tag.type){case 8:return quote((String)tag.value);case 1:return tag.value+"b";case 2:return tag.value+"s";case 4:return tag.value+"L";case 5:return tag.value+"f";case 6:return tag.value+"d";case 10:{StringBuilder b=new StringBuilder("{");for(Map.Entry<String,Tag> e:map(tag).entrySet()){if(b.length()>1)b.append(',');b.append(quote(e.getKey())).append(':').append(encode(e.getValue()));}return b.append('}').toString();}case 9:{StringBuilder b=new StringBuilder("[");for(Tag t:list(tag)){if(b.length()>1)b.append(',');b.append(encode(t));}return b.append(']').toString();}case 7:{StringBuilder b=new StringBuilder("[B;");for(byte n:(byte[])tag.value){if(b.length()>3)b.append(',');b.append(n).append('B');}return b.append(']').toString();}case 11:{StringBuilder b=new StringBuilder("[I;");for(int n:(int[])tag.value){if(b.length()>3)b.append(',');b.append(n);}return b.append(']').toString();}default:return String.valueOf(tag.value);}}
 static Tag parse(String text)throws IOException{Parser parser=new Parser(text);Tag value=parser.value(0);parser.ws();if(parser.pos!=text.length())throw new IOException("Trailing SNBT");return value;}
 static boolean preserves(Tag expected,Tag actual){
  if(actual==null)return false;
  if(expected.type==10){if(actual.type!=10)return false;for(Map.Entry<String,Tag> e:map(expected).entrySet())if(!preserves(e.getValue(),map(actual).get(e.getKey())))return false;return true;}
  if(expected.type==9){if(actual.type!=9||list(expected).size()!=list(actual).size())return false;for(int i=0;i<list(expected).size();i++)if(!preserves(list(expected).get(i),list(actual).get(i)))return false;return true;}
  if(expected.value instanceof Number&&actual.value instanceof Number)return expected.value.toString().equals(actual.value.toString());
  return encode(expected).equals(encode(actual));
 }
 static final class Parser {
  final String text;int pos;Parser(String text){this.text=text;}void ws(){while(pos<text.length()&&Character.isWhitespace(text.charAt(pos)))pos++;}char peek()throws IOException{ws();if(pos>=text.length())throw new IOException("Unexpected SNBT end");return text.charAt(pos);}void expect(char c)throws IOException{if(peek()!=c)throw new IOException("Expected "+c+" at "+pos);pos++;}
  String quoted()throws IOException{char q=text.charAt(pos++);StringBuilder b=new StringBuilder();while(pos<text.length()){char c=text.charAt(pos++);if(c==q)return b.toString();if(c=='\\'){if(pos>=text.length())throw new IOException("Bad escape");c=text.charAt(pos++);}b.append(c);}throw new IOException("Unclosed string");}
  String token(boolean key)throws IOException{if(peek()=='\"'||peek()=='\'')return quoted();int start=pos;while(pos<text.length()){char c=text.charAt(pos);if(c==','||c=='}'||c==']'||Character.isWhitespace(c)||(key&&c==':'))break;pos++;}if(pos==start)throw new IOException("Missing SNBT token");return text.substring(start,pos);}
  Tag value(int depth)throws IOException{if(depth>128)throw new IOException("NBT nesting too deep");char c=peek();if(c=='{'){pos++;Tag tag=compound();while(peek()!='}'){String key=token(true);expect(':');map(tag).put(key,value(depth+1));if(peek()!=',')break;pos++;}expect('}');return tag;}if(c=='['){pos++;ws();char arrayType=0;if(pos+1<text.length()&&text.charAt(pos+1)==';'){arrayType=Character.toUpperCase(text.charAt(pos));pos+=2;}List<Tag> values=new ArrayList<Tag>();while(peek()!=']'){values.add(value(depth+1));if(peek()!=',')break;pos++;}expect(']');if(arrayType==0)return new Tag(9,values);if(arrayType=='B'){byte[] a=new byte[values.size()];for(int i=0;i<a.length;i++)a[i]=((Number)values.get(i).value).byteValue();return new Tag(7,a);}if(arrayType=='I'){int[] a=new int[values.size()];for(int i=0;i<a.length;i++)a[i]=((Number)values.get(i).value).intValue();return new Tag(11,a);}throw new IOException("Long arrays cannot be represented by Minecraft 1.7.10");}if(c=='\"'||c=='\'')return new Tag(8,quoted());String s=token(false);try{char suffix=Character.toLowerCase(s.charAt(s.length()-1));String n=s.substring(0,s.length()-1);switch(suffix){case 'b':return new Tag(1,Byte.parseByte(n));case 's':return new Tag(2,Short.parseShort(n));case 'l':return new Tag(4,Long.parseLong(n));case 'f':return new Tag(5,Float.parseFloat(n));case 'd':return new Tag(6,Double.parseDouble(n));}if(s.equalsIgnoreCase("true")||s.equalsIgnoreCase("false"))return new Tag(1,(byte)(Boolean.parseBoolean(s)?1:0));if(s.matches("[-+]?[0-9]+"))return new Tag(3,Integer.parseInt(s));if(s.matches("[-+]?[0-9.]+([eE][-+]?[0-9]+)?"))return new Tag(6,Double.parseDouble(s));}catch(NumberFormatException ignored){}return new Tag(8,s);}
 }
}
